type inputConverter interface {
	GetIndex() int
	GetStatus() CompletionStatus
	GetMsgSender() string
	GetTimestamp() string
	GetBlockNumber() string
	GetPayload() string
}

func newInput(node inputConverter) (*Input, error) {
	timestamp, err := strconv.ParseUint(node.GetTimestamp(), 0, 64)
	if err != nil {
		return nil, fmt.Errorf("failed to parse timestamp: %v", err)
	}

	blocknumber, err := strconv.ParseUint(node.GetBlockNumber(), 0, 64)
	if err != nil {
		return nil, fmt.Errorf("failed to parse block number: %v", err)
	}

	payload, err := hexutil.Decode(node.GetPayload())
	if err != nil {
		return nil, fmt.Errorf("failed to decode payload to bytes: %v", err)
	}

	input := Input{
		node.GetIndex(),
		node.GetStatus(),
		common.HexToAddress(node.GetMsgSender()),
		time.Duration(timestamp),
		blocknumber,
		payload,
	}

	return &input, nil
}

func GetInput(
	ctx context.Context,
	client graphql.Client,
	index int,
) (*Input, error) {
	resp, err := getInput(ctx, client, int(index))
	if err != nil {
		return nil, err
	}

	return newInput(&resp.Input)
}

for _, edge := range resp.Inputs.Edges {
	input, err := newInput(&edge.Node)
	if err != nil {
		return nil, err
	}

	inputs = append(inputs, *input)
}
